// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }
    function testRegression_property() public {
        address depositor = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;
        vm.prank(depositor);
        c.setL1BlockValues(
            uint64(42),
            uint64(100),
            uint256(200),
            bytes32(hex"01"),
            uint64(300),
            bytes32(hex"02"),
            uint256(400),
            uint256(500)
        );
        assertTrue(c.number() == 42);
    }
}
